// Turns a *verified* Stripe Checkout session into a licence row — or, when
// the run came from the Manual Trigger, the details Eric typed into the
// "Manual request" node.
//
// Stripe path: the event body that reached the webhook is not trusted. The
// previous node re-fetched the session straight from the Stripe API using our
// own secret key, and the IF before this one dropped anything that is not
// actually paid. So everything below reads from the re-fetched session, never
// from the posted payload. The node right before this one looked the session
// up in the licence table: a row that already exists means Stripe delivered
// this event before (it retries on anything but a 2xx) and the customer may
// already hold that key — so it is kept, never rotated.
//
// Manual path: someone wrote in with an old licence (pre-Stripe, lost, or
// otherwise unusable) and needs a fresh key — or bought a Team plan by email.
// There is no Stripe session, so the row gets a synthetic session id, a
// brand-new key, and the normal licence email goes out. Any old row that
// customer has is left untouched; deactivate it by hand in the data table if
// it should stop validating.
//
// Three plans: `pro` (one seat, perpetual), `commercial` (the purchased seats,
// perpetual) and `team` (the purchased seats, a yearly subscription — the row
// expires, and "Team change" moves the date on every paid renewal).

// Crockford-ish alphabet: no I, O, 0 or 1, so a key read off a screen and
// typed into the app cannot be ambiguous.
const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
function block(n) {
  let bytes = null;
  try {
    bytes = globalThis.crypto.getRandomValues(new Uint8Array(n));
  } catch (e) {
    bytes = null;
  }
  let out = '';
  for (let i = 0; i < n; i++) {
    const v = bytes ? bytes[i] : Math.floor(Math.random() * 256);
    out += ALPHABET[v % ALPHABET.length];
  }
  return out;
}
function newKey() {
  return ['WSLM', block(5), block(5), block(5), block(5)].join('-');
}
// Perpetual. The validator compares against this date, so a null would read
// as expired rather than as "never expires".
const NEVER = '2099-12-31T00:00:00.000Z';

// A Team licence is billed yearly. The session does not say when the first
// period ends, so the row is written a year ahead plus a grace period; the
// first renewal invoice then moves it to the period Stripe actually billed.
// The grace outlasts Stripe's retries of a failed card (about two weeks), so
// a renewal that needs a second attempt never locks a team out.
const TEAM_TERM_DAYS = 365;
const TEAM_GRACE_DAYS = 14;
function teamExpiry(now) {
  return new Date(
    now.getTime() + (TEAM_TERM_DAYS + TEAM_GRACE_DAYS) * 86400000
  ).toISOString();
}

const PER_SEAT = ['commercial', 'team'];

// The plan a session was sold as: the Payment Link's `tier` metadata, which
// Stripe copies onto the session, or failing that the price's lookup key
// (`team_seat_year`, `commercial_seat`, `pro_windows`, `pro_macos`).
function tierOf(session) {
  const meta = String((session.metadata && session.metadata.tier) || '')
    .trim()
    .toLowerCase();
  if (meta) return meta;
  const items = (session.line_items && session.line_items.data) || [];
  const keys = Array.isArray(items)
    ? items.map((i) => String((i && i.price && i.price.lookup_key) || ''))
    : [];
  if (keys.some((k) => k.startsWith('team'))) return 'team';
  if (keys.some((k) => k.startsWith('commercial'))) return 'commercial';
  return 'pro';
}

function manualLicence(input, now) {
  const email = String(input.email || '').trim();
  if (!email || !email.includes('@')) {
    throw new Error('Manual request: fill in the customer\'s email address first');
  }
  const asked = String(input.plan || 'pro').trim().toLowerCase();
  const tier = PER_SEAT.includes(asked) ? asked : 'pro';
  const seats = PER_SEAT.includes(tier)
    ? Math.max(1, Math.floor(Number(input.seats)) || 1)
    : 1;
  const stamp = now.toISOString().slice(0, 10).replace(/-/g, '');
  return {
    license_key: newKey().toLowerCase(),
    resent: false,
    email,
    company: PER_SEAT.includes(tier) ? String(input.company || '').trim() : '',
    stripe_id: '',
    // Unique, so the upsert in Save licence inserts a new row, and
    // recognisable in the table as a hand-issued replacement.
    session_id: `manual_${stamp}_${block(8).toLowerCase()}`,
    plan: tier,
    seats,
    // A hand-issued Team licence has no subscription to renew it: it runs
    // for the year and is extended by hand in the data table.
    expires: tier === 'team' ? teamExpiry(now) : NEVER,
  };
}

function sessionLicence(session, existing, now) {
  // Seats come from the purchased quantity, so a promo code cannot skew the
  // count the way dividing amount_total by the unit price would.
  let seats = 1;
  try {
    const items = session.line_items && session.line_items.data;
    if (Array.isArray(items) && items.length) {
      seats = items.reduce((n, i) => n + (i.quantity || 0), 0) || 1;
    }
  } catch (e) {
    seats = 1;
  }

  const key = existing.license_key ? String(existing.license_key) : newKey();
  const tier = tierOf(session);
  const details = session.customer_details || {};

  // A redelivered event keeps the date the row already carries: by then a
  // renewal may have moved it, and this must not move it back.
  const kept = existing.license_key && existing.expires
    ? new Date(existing.expires)
    : null;
  const expires = tier !== 'team'
    ? NEVER
    : kept && !Number.isNaN(kept.getTime())
      ? kept.toISOString()
      : teamExpiry(now);

  return {
    // Stored lower-case so lookups are case-insensitive; the website and the
    // app upper-case it for display.
    license_key: key.toLowerCase(),
    // Whether this event had been seen before; the email is only sent once.
    resent: !!existing.license_key,
    email: session.customer_email || details.email || '',
    company: PER_SEAT.includes(tier)
      ? (details.business_name || details.name || '')
      : '',
    stripe_id: session.customer || '',
    session_id: session.id,
    plan: tier,
    seats: PER_SEAT.includes(tier) ? seats : 1,
    expires,
  };
}

// --- n8n Code node entry point -------------------------------------------
// Present only inside n8n; under `node` this falls through to the export.
if (typeof $input !== 'undefined') {
  const input = $input.first().json || {};
  if (input.source === 'manual') {
    return [{ json: manualLicence(input, new Date()) }];
  }
  const session = $('Re-fetch session').item.json;
  return [{ json: sessionLicence(session, input, new Date()) }];
}

module.exports = {
  manualLicence,
  sessionLicence,
  tierOf,
  teamExpiry,
  newKey,
  NEVER,
  TEAM_TERM_DAYS,
  TEAM_GRACE_DAYS,
};

// Writes the licence email. Everything comes from Build licence, which read
// the re-fetched, verified Stripe session; Save licence has just stored the
// same row. Plain HTML with inline styles so every mail client renders it.
function compose(licence) {
const key = String(licence.license_key || '').toUpperCase();
const commercial = licence.plan === 'commercial';
const team = licence.plan === 'team';
const seats = Number(licence.seats) || 1;
const to = String(licence.email || '').trim();
const sessionId = String(licence.session_id || '');

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[c]));

const product = commercial
  ? 'WSL Manager Commercial'
  : team
    ? 'WSL Manager Team'
    : 'WSL Manager Pro';
// A Team licence runs for the year that was billed; say until when.
const until = team && licence.expires && !Number.isNaN(new Date(licence.expires).getTime())
  ? new Date(licence.expires).toISOString().slice(0, 10)
  : '';
const seatText = seats === 1 ? '1 seat' : `${seats} seats`;
const licencePage = `https://wslmanager.com/buy/success/?session_id=${encodeURIComponent(sessionId)}`;

const intro = commercial
  ? `Thank you for buying a commercial licence for WSL Manager — ${seatText}, perpetual, no renewal. Share the key below with your team; each person pastes it into their own install.`
  : team
    ? `Thank you for choosing the WSL Manager Team plan — ${seatText}, renewing every year${until ? ` (the current period runs until ${until})` : ''}. Share the key below with your team; each person pastes it into their own install, and once every seat is taken the newest activation wins.`
    : 'Thank you for buying WSL Manager Pro. Your licence is perpetual and covers every machine you use yourself. Here is your key:';

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Your ${esc(product)} licence key</title>
</head>
<body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111827;">
  <div style="display:none;max-height:0;overflow:hidden;">Your ${esc(product)} licence key is inside.</div>
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f3f4f6;padding:32px 16px;">
    <tr><td align="center">
      <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:560px;background:#ffffff;border-radius:16px;border:1px solid #e5e7eb;overflow:hidden;">
        <tr><td style="padding:28px 32px 0 32px;">
          <table role="presentation" cellspacing="0" cellpadding="0"><tr>
            <td style="vertical-align:middle;"><img src="https://wslmanager.com/img/logo.png" width="40" height="40" alt="" style="display:block;border-radius:10px;"></td>
            <td style="vertical-align:middle;padding-left:12px;font-size:18px;font-weight:600;color:#111827;">WSL Manager</td>
          </tr></table>
        </td></tr>
        <tr><td style="padding:28px 32px 0 32px;">
          <h1 style="margin:0;font-size:26px;line-height:1.25;font-weight:600;letter-spacing:-0.01em;color:#111827;">You&rsquo;re all set</h1>
          <p style="margin:14px 0 0 0;font-size:16px;line-height:1.6;color:#4b5563;">${esc(intro)}</p>
        </td></tr>
        <tr><td style="padding:24px 32px 0 32px;">
          <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:12px;">
            <tr><td style="padding:18px 20px;">
              <p style="margin:0 0 8px 0;font-size:11px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:#6b7280;">Your licence key</p>
              <p style="margin:0;font-family:SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace;font-size:18px;line-height:1.5;letter-spacing:0.02em;color:#111827;word-break:break-all;">${esc(key)}</p>
            </td></tr>
          </table>
        </td></tr>
        <tr><td style="padding:24px 32px 0 32px;">
          <p style="margin:0 0 10px 0;font-size:15px;font-weight:600;color:#111827;">How to activate</p>
          <ol style="margin:0;padding-left:20px;font-size:15px;line-height:1.7;color:#4b5563;">
            <li>Open WSL Manager on Windows or macOS.</li>
            <li>Go to <strong style="color:#111827;">Upgrade to Pro</strong> in the sidebar.</li>
            <li>Paste the key and press <strong style="color:#111827;">Activate</strong>.</li>
          </ol>
          <p style="margin:14px 0 0 0;font-size:14px;line-height:1.6;color:#6b7280;">Bought on your Mac? Your <a href="${licencePage}" style="color:#0891b2;text-decoration:none;font-weight:600;">licence page</a> has an <em>Activate in WSL Manager</em> button that hands the key to the app for you.</p>
        </td></tr>
        <tr><td style="padding:28px 32px 0 32px;">
          <table role="presentation" cellspacing="0" cellpadding="0"><tr>
            <td style="background:#06b6d4;border-radius:10px;">
              <a href="${licencePage}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;">Open your licence page</a>
            </td>
          </tr></table>
        </td></tr>
        <tr><td style="padding:28px 32px 28px 32px;">
          <p style="margin:0;font-size:13px;line-height:1.6;color:#6b7280;">Keep this email — it is your proof of purchase. Questions, more seats, or a lost key: reply to this email or write to <a href="mailto:license@bostrot.com" style="color:#0891b2;text-decoration:none;">license@bostrot.com</a>.</p>
        </td></tr>
      </table>
      <p style="margin:18px 0 0 0;font-size:12px;line-height:1.6;color:#9ca3af;">Sent by Eric Trenkel &middot; WSL Manager &middot; <a href="https://wslmanager.com" style="color:#9ca3af;text-decoration:none;">wslmanager.com</a></p>
    </td></tr>
  </table>
</body>
</html>`;

const text = [
  `Thank you for buying ${product}${commercial ? ` (${seatText})` : ''}${team ? ` (${seatText}, renews yearly${until ? `, current period until ${until}` : ''})` : ''}.`,
  '',
  `Your licence key: ${key}`,
  '',
  'How to activate: open WSL Manager, go to "Upgrade to Pro" in the sidebar, paste the key and press Activate.',
  `Your licence page: ${licencePage}`,
  '',
  'Keep this email as your proof of purchase. Questions or a lost key: license@bostrot.com',
].join('\n');

return {
  to,
  subject: `Your ${product} licence key`,
  html,
  text,
  // Nothing to send to; the row is saved and the licence page still works.
  skip: !to || licence.resent === true,
};
}

// --- n8n Code node entry point -------------------------------------------
// Present only inside n8n; under `node` this falls through to the export.
if (typeof $input !== 'undefined') {
  return [{ json: compose($('Build licence').item.json) }];
}

module.exports = { compose };

// What a Team subscription's later life does to its licence row.
//
// Two Stripe events reach this node, both re-fetched from the Stripe API by
// the node before the last (the posted payload is never trusted):
//
//   invoice.paid                   the subscription was billed for another
//                                  year: the row runs until that period
//                                  ends, plus the grace, and is active again
//                                  if it had lapsed.
//   customer.subscription.deleted  the subscription is over: the row stops
//                                  validating.
//
// A renewal that *fails* sends nothing here and needs nothing done: the row
// keeps the date its last paid invoice set and lapses on its own once Stripe
// has given up retrying the card.
//
// The rows are the customer's (the node before this one fetched them by
// `stripe_id`), and only the ones whose plan is `team` are ever touched — a
// Pro or Commercial key the same customer bought is perpetual and stays so.
// The licence table has no subscription column, so a customer with two Team
// subscriptions has both rows follow either one; that is what the licence
// server (wslmanager-license) fixes, and why this is the interim.

// Same grace as "Build licence": longer than Stripe retries a failed card.
const TEAM_GRACE_DAYS = 14;

const NONE = { action: 'none' };

function customerOf(object) {
  const c = object.customer;
  if (typeof c === 'string') return c;
  return c && typeof c.id === 'string' ? c.id : '';
}

// The subscription an invoice bills, wherever the API version put it.
function subscriptionOf(invoice) {
  const parent = invoice.parent && invoice.parent.subscription_details;
  const sub = invoice.subscription || (parent && parent.subscription);
  if (typeof sub === 'string') return sub;
  return sub && typeof sub.id === 'string' ? sub.id : '';
}

/**
 * What a re-fetched Stripe object asks for: `renew` until a date, `cancel`,
 * or nothing.
 */
function decide(object) {
  if (!object || typeof object !== 'object') return NONE;
  const customer = customerOf(object);
  if (!customer) return NONE;

  if (object.object === 'invoice') {
    // A one-off invoice (a Commercial purchase sends one too) renews nothing.
    if (object.status !== 'paid' || !subscriptionOf(object)) return NONE;
    const lines = (object.lines && object.lines.data) || [];
    const ends = (Array.isArray(lines) ? lines : [])
      .map((l) => l && l.period && Number(l.period.end))
      .filter((n) => Number.isFinite(n) && n > 0);
    if (!ends.length) return NONE;
    const until = new Date(
      (Math.max(...ends) + TEAM_GRACE_DAYS * 86400) * 1000
    ).toISOString();
    return { action: 'renew', customer, until };
  }

  if (object.object === 'subscription') {
    if (object.status !== 'canceled') return NONE;
    return { action: 'cancel', customer };
  }

  return NONE;
}

function iso(value) {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

/**
 * The updates to write: one per Team row, as `{row_id, active, expires}`.
 * A renewal never moves a date backwards — an invoice for a short period
 * (a proration, a seat added mid-year) must not cut the year short.
 */
function changes(rows, decision) {
  if (!decision || decision.action === 'none') return [];
  return (Array.isArray(rows) ? rows : [])
    .filter((r) => r && r.id !== undefined && r.id !== null)
    .filter((r) => String(r.plan || '').toLowerCase() === 'team')
    .filter((r) => !decision.customer || r.stripe_id === decision.customer)
    .map((r) => {
      const current = iso(r.expires);
      if (decision.action === 'cancel') {
        return { row_id: r.id, active: false, expires: current || decision.until || new Date(0).toISOString() };
      }
      const later = current && current > decision.until ? current : decision.until;
      return { row_id: r.id, active: true, expires: later };
    });
}

// --- n8n Code node entry point -------------------------------------------
// Present only inside n8n; under `node` this falls through to the export.
if (typeof $input !== 'undefined') {
  const object = $('Re-fetch object').first().json || {};
  const rows = $input.all().map((i) => i.json || {});
  return changes(rows, decide(object)).map((json) => ({ json }));
}

module.exports = { decide, changes, subscriptionOf, TEAM_GRACE_DAYS };
